"""Finish analysis of terminal native jobs only; never repeat restart/removal."""
from pathlib import Path
import json,re,hashlib
w=Path(__file__).resolve().parent;p=w/'private';sha=lambda f:hashlib.sha256(f.read_bytes()).hexdigest()
receipt=lambda n:json.loads((p/(n+'-receipt.json')).read_text())
for n in ['native-load-PnP','native-first-status','native-PnP-restart','native-after-restart-status','native-exact-package-uninstall','native-after-uninstall-inventory','native-release-debug-witness']:
 r=receipt(n);assert r['status']=='ok'and r.get('exit_code',0)==0,n
initial=json.loads(receipt('native-first-status')['output'])['status'];again=json.loads(receipt('native-after-restart-status')['output'])['status']
for s in [initial,again]:assert s['KernelBuild']==26100 and s['Cpus']==8 and s['Irql']==0 and s['FirmwareMatch']==1 and s['Prepared']==s['D0Active']==s['D0Epoch']==s['PrepareEpoch']==1 and s['MapCount']==s['MapCalls']==20 and not any(s[n]for n in ['UnmapCalls','ReleaseCalls','ValidationCode','LastStatus','ProducerQualified'])
contract=json.loads((w/'resource-contract.json').read_text())['resources'];expected=sorted((r['base'],r['base']+r['bytes']-1)for r in contract)
for n in ['native-namespace-after','native-after-restart-inventory']:
 text=receipt(n)['output'];got=sorted((int(a,16),int(b,16))for a,b in re.findall(r'0x([0-9A-Fa-f]+)\s*-\s*0x([0-9A-Fa-f]+)',text));assert got==expected and 'Service:                    OpenG182'in text and 'Status:                     Started'in text
v=json.loads((p/'native-release-debug.json').read_text());assert len(v['release_lines'])==2;lines=[]
for item in v['release_lines']:
 line=item['value']if isinstance(item,dict)else item;m=re.search(r'maps_before=(\d+) maps_after=(\d+) map_calls=(\d+) unmap_calls=(\d+) releases=(\d+) prepared=(\d+) producer=(\d+)',line);assert m and list(map(int,m.groups()))==[20,0,20,20,1,0,0];lines.append(line)
r=receipt('native-interface-absent');assert r['status']=='error'and r['exit_code']==1;assert 'interface size'in json.loads(r['output'])['error'];assert 'OpenG182'not in receipt('native-after-uninstall-inventory')['output']
life=json.loads((p/'native-lifetime.json').read_text());life.update(phase='native_restart_and_release_qualified',complete=True,release_lines=lines,interface_absent=True,analysis_only_completion=True);(p/'native-lifetime.json').write_text(json.dumps(life,indent=2)+'\n')
boot=json.loads((p/'corrected-launch.json').read_text());assert boot['phase']=='temporary_boot_command_accepted'and boot['partition_flash_commands']==0
v=json.loads(receipt('postboot-loader-inspect')['output']);assert v['phase']=='G154_inspect'
proof={'passed':True,'session':life['session'],'native_assigned_ranges_match_all20':True,'initial':initial,'after_restart':again,'restart_created_new_driver_context':True,'native_release_callbacks':2,'native_maps_released_per_instance':20,'native_release_lines':lines,'test_package_removed_from_RAM':life['published_INF'],'interface_absent_after_uninstall':True,'DSP_report_fresh_validated':True,'software_fastboot_cycle_completed':10,'ESP_original_loader_inspected_after_boot':True,'source_register_actions':0,'ProducerQualified':0,'partition_flashes':0,'same_boot_PAS_retries':0,'image_sha256':sha(p/'boot-G182-resources.img'),'driver_sha256':sha(p/'OpenG182.sys'),'catalog_sha256':sha(p/'OpenG182.cat'),'corrected_host_guard':'First watcher stopped before boot at a wrong expected log path; corrected in the same fastboot session,then exactly one temporary image boot accepted.','analysis_correction':'PowerShell Get-Content strings serialized as value/metadata objects; saved terminal log output analyzed without replaying any operation.','limits':['Native resource/D0/restart/release qualification only. No sensor,GLINK,charger,battery,touch or register action.','PnP restart creates a new driver context; this is not same-object sleep/wake or hardware power readiness proof.','No native allocation-failure/timeout injection; those callback failures remain modeled.','Always-on clocks/pins,normal-Windows shared owners,continuous physical producer and battery-class integration remain unqualified.'],'evidence_sha256':{n:sha(p/n)for n in ['native-first-status.json','native-release-debug.json','native-lifetime.json','fresh-DSP-report.json','publisher-replay.json','image-audit.json']}}
(p/'native-analysis.json').write_text(json.dumps(proof,indent=2)+'\n');print({k:proof[k]for k in ['passed','session','native_assigned_ranges_match_all20','native_release_callbacks','software_fastboot_cycle_completed','ProducerQualified']})
